// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address nonOwner, address newOwner) public {
        address currentOwner = c.owner();
        vm.assume(nonOwner != currentOwner);
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != currentOwner);

        vm.prank(currentOwner);

        address ownerBefore = c.owner();
        vm.prank(nonOwner);
        bool success = false;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        address ownerAfter = c.owner();

        assertTrue((nonOwner == ownerBefore) || (ownerAfter == ownerBefore));
    }
}
